item.command:
/bin/bash -lc "python - <<'PY'
import csv
sets={}
for strain in ('97','98','99'):
  for direction in ('pos','neg'):
    path=f'galaxy_outputs/{strain}_{direction}_ora.tsv'
    with open(path) as f:
      rows=csv.DictReader(f,delimiter='\\t')
      sig=[(r['pathway_id'],r['pathway_name'],float(r['adjusted_p_value'])) for r in rows if float(r['adjusted_p_value'])<0.05]
    sets[(strain,direction)]={x[0] for x in sig}
    print(strain,direction,len(sig))
    for x in sig: print(' ',x)
for direction in ('pos','neg'):
  common=set.intersection(*(sets[(s,direction)] for s in ('97','98','99')))
  print('COMMON',direction,len(common),sorted(common))
print('TOTAL',sum(len(set.intersection(*(sets[(s,d)] for s in ('97','98','99')))) for d in ('pos','neg')))
PY"

